def check_inequality(a_i, a_j):
    # Constraint: 3(a_i^2 + a_j^2) + 15 >= (a_i a_j + 4)^2
    lhs = 3 * (a_i**2 + a_j**2) + 15
    rhs = (a_i * a_j + 4)**2
    return lhs >= rhs

# Proposed set: {0.1, 0.5, 5, 10}
A = [0.1, 0.5, 5, 10]
print(f"Testing set A = {A}")

N = len(A)
all_pass = True
test_results = []

for i in range(N):
    for j in range(i + 1, N):
        a_i = A[i]
        a_j = A[j]
        pass_check = check_inequality(a_i, a_j)
        test_results.append(((a_i, a_j), pass_check))
        if not pass_check:
            all_pass = False

print("\n--- Test Results ---")
for (pair, passed) in test_results:
    print(f"Pair {pair}: {'PASS' if passed else 'FAIL'}")

if all_pass:
    print("\nSUCCESS: All 6 pairs satisfy the inequality.")
else:
    print("\nFAILURE: At least one pair failed the inequality.")

